"kind": "propose",
"summary": "Readiness probe timeout is too short for the new version, causing 503 errors. Increase timeout to match periodSeconds.",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Readiness probe timeout (2s) is shorter than the app's response time, causing 503 errors.",
    "supporting": ["probe_timeouts = false", "ev-target_events"],
    "contradicting": ["probe_kills = false"],
    "missing": ["container_logs_tail", "revision_health"],
    "status": "supported"
  },
  {
    "root_cause_class": "still_starting",
    "summary": "Pods are running but not responding to readiness probes quickly enough.",
    "supporting": ["ev-pod_states", "ev-target_events"],
    "contradicting": ["crashed_on_its_own = false"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "Missing container logs to confirm if the app is responding or if the probe is misconfigured.",
    "supporting": ["container_logs_tail = empty"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "orders",
    "uid": "uid-deployment-orders"
  },
  "params": {
    "container": "app",
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Readiness probe timeout increased to 5s to accommodate app startup time, preventing premature 503 errors.",
  "rationale": "Readiness probe timeout (2s) is shorter than the app's response time, causing 503 errors. Increasing timeout to 5s matches the periodSeconds and allows the app to respond before probe failure.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states"],
  "cited_predicates": ["probe_timeouts", "probe_kills", "crashed_on_its_own"]
}
}
